//! The single error type OAGW renders on the wire.
//!
//! Every variant maps to one row of the error table in `docs/DESIGN.md` §3.3:
//! an HTTP status, a GTS `type` identifier, and — per
//! `ADR/0007-error-source-distinction.md` — an `X-OAGW-Error-Source` value.

use serde_json::{Map, Value, json};
use std::fmt;

use super::gts_helpers::errors;

/// Whether an error was produced by the gateway or passed through from the
/// upstream service (`ADR/0007-error-source-distinction.md`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorSource {
    /// Generated by OAGW.
    Gateway,
    /// Produced by the upstream service and forwarded unchanged.
    Upstream,
}

impl ErrorSource {
    /// Wire value of the `X-OAGW-Error-Source` header.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Gateway => "gateway",
            Self::Upstream => "upstream",
        }
    }
}

/// A gateway-side failure.
///
/// Construction is deliberately data-only: the transport layer turns this into
/// an RFC 9457 `application/problem+json` body (see
/// `crate::api::rest::error`), so the domain never depends on Axum.
#[derive(Debug, Clone)]
pub struct DomainError {
    status: u16,
    gts_type: &'static str,
    title: &'static str,
    detail: String,
    /// Extension members (`upstream_id`, `valid_hosts`, …).
    extensions: Map<String, Value>,
    /// Seconds the client should wait before retrying, when known.
    retry_after_seconds: Option<u64>,
}

impl DomainError {
    /// Build an error from its status, GTS type, title and detail.
    #[must_use]
    pub fn new(
        status: u16,
        gts_type: &'static str,
        title: &'static str,
        detail: impl Into<String>,
    ) -> Self {
        Self {
            status,
            gts_type,
            title,
            detail: detail.into(),
            extensions: Map::new(),
            retry_after_seconds: None,
        }
    }

    /// Attach an RFC 9457 extension member.
    #[must_use]
    pub fn with_extension(mut self, key: &str, value: impl Into<Value>) -> Self {
        self.extensions.insert(key.to_owned(), value.into());
        self
    }

    /// Attach retry guidance; also drives the `Retry-After` response header.
    #[must_use]
    pub fn with_retry_after(mut self, seconds: u64) -> Self {
        self.retry_after_seconds = Some(seconds);
        self.extensions
            .insert("retry_after_seconds".to_owned(), json!(seconds));
        self
    }

    /// HTTP status code.
    #[must_use]
    pub const fn status(&self) -> u16 {
        self.status
    }

    /// GTS `type` identifier.
    #[must_use]
    pub const fn gts_type(&self) -> &'static str {
        self.gts_type
    }

    /// Human-readable summary.
    #[must_use]
    pub const fn title(&self) -> &'static str {
        self.title
    }

    /// Occurrence-specific explanation.
    #[must_use]
    pub fn detail(&self) -> &str {
        &self.detail
    }

    /// Retry guidance in seconds, when the variant carries any.
    #[must_use]
    pub const fn retry_after_seconds(&self) -> Option<u64> {
        self.retry_after_seconds
    }

    /// Extension members attached to this occurrence.
    #[must_use]
    pub const fn extensions(&self) -> &Map<String, Value> {
        &self.extensions
    }

    // -- constructors, one per documented row -------------------------------

    /// `400` — request or configuration validation failed.
    #[must_use]
    pub fn validation(detail: impl Into<String>) -> Self {
        Self::new(400, errors::VALIDATION, "Validation Error", detail)
    }

    /// `400` — `X-OAGW-Target-Host` is required for this upstream.
    #[must_use]
    pub fn missing_target_host(detail: impl Into<String>) -> Self {
        Self::new(
            400,
            errors::MISSING_TARGET_HOST,
            "Missing Target Host Header",
            detail,
        )
    }

    /// `400` — `X-OAGW-Target-Host` is not a bare hostname or IP.
    #[must_use]
    pub fn invalid_target_host(detail: impl Into<String>) -> Self {
        Self::new(
            400,
            errors::INVALID_TARGET_HOST,
            "Invalid Target Host Format",
            detail,
        )
    }

    /// `400` — `X-OAGW-Target-Host` names no configured endpoint.
    #[must_use]
    pub fn unknown_target_host(detail: impl Into<String>) -> Self {
        Self::new(
            400,
            errors::UNKNOWN_TARGET_HOST,
            "Unknown Target Host",
            detail,
        )
    }

    /// `401` — outbound authentication could not be prepared.
    #[must_use]
    pub fn authentication_failed(detail: impl Into<String>) -> Self {
        Self::new(401, errors::AUTH_FAILED, "Authentication Failed", detail)
    }

    /// `403` — the caller is not permitted to perform the operation.
    #[must_use]
    pub fn forbidden(detail: impl Into<String>) -> Self {
        Self::new(403, errors::FORBIDDEN, "Forbidden", detail)
    }

    /// `403` — CORS origin rejected on an actual cross-origin request.
    #[must_use]
    pub fn cors_origin_not_allowed(detail: impl Into<String>) -> Self {
        Self::new(
            403,
            errors::CORS_ORIGIN_NOT_ALLOWED,
            "CORS Origin Not Allowed",
            detail,
        )
    }

    /// `403` — CORS method rejected on an actual cross-origin request.
    #[must_use]
    pub fn cors_method_not_allowed(detail: impl Into<String>) -> Self {
        Self::new(
            403,
            errors::CORS_METHOD_NOT_ALLOWED,
            "CORS Method Not Allowed",
            detail,
        )
    }

    /// `404` — no upstream, route or resource matched.
    #[must_use]
    pub fn not_found(detail: impl Into<String>) -> Self {
        Self::new(404, errors::ROUTE_NOT_FOUND, "Route Not Found", detail)
    }

    /// `409` — natural-key conflict (alias, match rule, plugin name).
    #[must_use]
    pub fn conflict(detail: impl Into<String>) -> Self {
        Self::new(409, errors::CONFLICT, "Conflict", detail)
    }

    /// `409` — the plugin is still referenced by upstreams or routes.
    #[must_use]
    pub fn plugin_in_use(detail: impl Into<String>) -> Self {
        Self::new(409, errors::PLUGIN_IN_USE, "Plugin In Use", detail)
    }

    /// `413` — request payload exceeds the hard body limit.
    #[must_use]
    pub fn payload_too_large(detail: impl Into<String>) -> Self {
        Self::new(413, errors::PAYLOAD_TOO_LARGE, "Payload Too Large", detail)
    }

    /// `429` — the effective rate limit rejected the request.
    #[must_use]
    pub fn rate_limit_exceeded(detail: impl Into<String>) -> Self {
        Self::new(
            429,
            errors::RATE_LIMIT_EXCEEDED,
            "Rate Limit Exceeded",
            detail,
        )
    }

    /// `500` — a `cred://` reference could not be resolved.
    #[must_use]
    pub fn secret_not_found(detail: impl Into<String>) -> Self {
        Self::new(500, errors::SECRET_NOT_FOUND, "Secret Not Found", detail)
    }

    /// `500` — unexpected internal failure.
    #[must_use]
    pub fn internal(detail: impl Into<String>) -> Self {
        Self::new(500, errors::INTERNAL, "Internal Error", detail)
    }

    /// `501` — catalogued but not implemented in this build.
    #[must_use]
    pub fn not_implemented(detail: impl Into<String>) -> Self {
        Self::new(501, errors::NOT_IMPLEMENTED, "Not Implemented", detail)
    }

    /// `502` — protocol-level failure talking to the upstream.
    #[must_use]
    pub fn protocol_error(detail: impl Into<String>) -> Self {
        Self::new(502, errors::PROTOCOL_ERROR, "Protocol Error", detail)
    }

    /// `502` — the upstream service reported a failure.
    #[must_use]
    pub fn downstream_error(detail: impl Into<String>) -> Self {
        Self::new(502, errors::DOWNSTREAM_ERROR, "Downstream Error", detail)
    }

    /// `502` — a stream was aborted before completing.
    #[must_use]
    pub fn stream_aborted(detail: impl Into<String>) -> Self {
        Self::new(502, errors::STREAM_ABORTED, "Stream Aborted", detail)
    }

    /// `503` — the upstream link is unavailable (disabled or unreachable).
    #[must_use]
    pub fn link_unavailable(detail: impl Into<String>) -> Self {
        Self::new(503, errors::LINK_UNAVAILABLE, "Link Unavailable", detail)
    }

    /// `503` — a bound plugin could not be resolved.
    #[must_use]
    pub fn plugin_not_found(detail: impl Into<String>) -> Self {
        Self::new(503, errors::PLUGIN_NOT_FOUND, "Plugin Not Found", detail)
    }

    /// `504` — the connection could not be established in time.
    #[must_use]
    pub fn connection_timeout(detail: impl Into<String>) -> Self {
        Self::new(
            504,
            errors::CONNECTION_TIMEOUT,
            "Connection Timeout",
            detail,
        )
    }

    /// `504` — the upstream exchange exceeded its budget.
    #[must_use]
    pub fn request_timeout(detail: impl Into<String>) -> Self {
        Self::new(504, errors::REQUEST_TIMEOUT, "Request Timeout", detail)
    }
}

impl fmt::Display for DomainError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} ({}): {}", self.title, self.status, self.detail)
    }
}

impl std::error::Error for DomainError {}

/// Convenience alias for fallible domain operations.
pub type DomainResult<T> = Result<T, DomainError>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn documented_status_and_type_pairs() {
        let cases: Vec<(DomainError, u16, &str)> = vec![
            (DomainError::validation("x"), 400, errors::VALIDATION),
            (
                DomainError::authentication_failed("x"),
                401,
                errors::AUTH_FAILED,
            ),
            (DomainError::not_found("x"), 404, errors::ROUTE_NOT_FOUND),
            (DomainError::plugin_in_use("x"), 409, errors::PLUGIN_IN_USE),
            (
                DomainError::payload_too_large("x"),
                413,
                errors::PAYLOAD_TOO_LARGE,
            ),
            (
                DomainError::rate_limit_exceeded("x"),
                429,
                errors::RATE_LIMIT_EXCEEDED,
            ),
            (
                DomainError::secret_not_found("x"),
                500,
                errors::SECRET_NOT_FOUND,
            ),
            (
                DomainError::downstream_error("x"),
                502,
                errors::DOWNSTREAM_ERROR,
            ),
            (
                DomainError::link_unavailable("x"),
                503,
                errors::LINK_UNAVAILABLE,
            ),
            (
                DomainError::request_timeout("x"),
                504,
                errors::REQUEST_TIMEOUT,
            ),
        ];
        for (err, status, gts) in cases {
            assert_eq!(err.status(), status, "{gts}");
            assert_eq!(err.gts_type(), gts);
        }
    }

    #[test]
    fn retry_after_lands_in_both_places() {
        let err = DomainError::rate_limit_exceeded("slow down").with_retry_after(15);
        assert_eq!(err.retry_after_seconds(), Some(15));
        assert_eq!(
            err.extensions().get("retry_after_seconds"),
            Some(&json!(15))
        );
    }

    #[test]
    fn error_source_wire_values() {
        assert_eq!(ErrorSource::Gateway.as_str(), "gateway");
        assert_eq!(ErrorSource::Upstream.as_str(), "upstream");
    }
}
